using System.Collections.Generic;

namespace FingerDiceDuel.Characters
{
    /// <summary>Chinese profession/subclass skills, synchronized with Docs/character-skill-copy-draft.md.</summary>
    public static class CharacterSkillText
    {
        private static readonly Dictionary<string, string> ById = new Dictionary<string, string>
        {
            { "fighter_champion", "战士｜职业：攻+1，防0，距离1，挥砍伤害。\n\n精通重击｜被动技能：用运算前为1的手发起攻击时，本次攻击的基础伤害×1.5，命中附带2回合物理易伤。" },
            { "fighter_breaker", "战士｜职业：攻+1，防0，距离1，挥砍伤害。\n\n破阵强袭｜主动技能：自己的盾牌破碎时，可以选择场上另一面完整盾牌，使其破碎；主动碎盾引发的破阵强袭先于本次攻击结算。\n\n无畏冲锋｜主动技能：发起攻击时，若另一只手持有完整盾牌，可以使其破碎，令本次攻击距离改为∞，命中附加2回合流血。\n\n破盾追击｜被动技能：使用自己的完整盾牌作为运算手并打出攻击时，本次攻击命中附加2回合流血。\n\n盾阵重整｜被动技能：形成盾牌时，若另一只手持有破碎盾牌，将其修复为完整盾牌。" },
            { "fighter_arcane_archer", "战士｜职业：攻+1，防0，距离1，挥砍伤害。\n\n魔射训练｜子职：攻−1，防−1，距离改为3，攻击改为穿刺伤害。\n\n奥术射击｜被动技能：以4发起攻击时，发动魔能齐射，改为两段各4点基础伤害的攻击；以6发起攻击时，发动强力射击，基础伤害+2；以8发起攻击时，发动穿透箭，无视盾牌。" },
            { "paladin_oath_of_the_crown", "圣武士｜职业：攻0，防0，距离1，钝击伤害。\n\n王冠武备｜子职：攻+1，防−1，攻击改为穿刺伤害。\n\n神圣誓忠｜被动技能：自己的盾牌每破碎一次，攻击距离永久+1；自身攻击加成始终等于攻击距离，初始均为1。" },
            { "paladin_oath_of_devotion", "圣武士｜职业：攻0，防0，距1，钝击。\n\n奉献灵光｜被动技能：4改为合盾，6正常攻击。\n\n卫护斩｜被动技能：合盾或碎盾时，对范围内一名其他角色造成固定2点冲击。\n\n守护之誓｜主动技能：持完整盾时，可替范围内的角色承受攻击。代挡碎盾也触发卫护斩。" },
            { "paladin_oathbreaker", "圣武士｜职业：攻0，防0，距离1，钝击伤害。\n\n破誓武备｜子职：攻+2。\n\n恐惧打击｜被动技能：运算打出5时，改为发起一次基础伤害为5的钝击攻击。\n\n憎恨灵光｜主动技能：受到攻击时，若手上有5，可以将本次攻击转移给另一名持有完整盾牌的角色，不能选择攻击者。" },
            { "cleric_knowledge_domain", "牧师｜职业：攻0，防−1，距离∞；近距离钝击、远距离穿刺。回复数字可选择其他存活角色。\n\n岁月知识｜被动技能：加法运算进位后，获得1层知识祝福。\n\n知识赐福｜被动技能：回复给目标1层知识祝福。\n\n知识祝福｜角色状态：层数保留到攻击，消耗全部层数；本次命中后独立追加等层力场伤害，并附困惑2回合。" },
            { "cleric_life_domain", "牧师｜职业：攻0，防−1，距离∞；距离1以内钝击伤害，距离超过1穿刺伤害。回复数字可选择给其他存活角色回复。\n\n生命修习｜子职：攻−1。\n\n生命门徒｜主动技能：可将4、6、8的攻击改为等量治疗；双手均为9时，额外为一名角色回复9点体力。\n\n神佑医者｜被动技能：治疗前净化。治疗溢出时，目标攻防+1，持续2回合。" },
            { "wizard_school_of_conjuration", "法师｜职业：攻0，防−1，距离∞；距离1以内钝击伤害，距离超过1穿刺伤害。\n\n咒法护身｜子职：防+1。\n\n次级咒术｜被动技能：攻−1，攻击改为力场伤害，无视盾牌、正防御与闪避，并穿透太极和伏击。\n\n王车易位｜主动技能：回合开始时，可以跳过本回合，选择一名双手点数与自己无序匹配的其他角色，交换双方座位，不限距离。距离立即更新，队友与对手关系不变，本轮按原顺序行动，下一轮按新座位顺序行动。" },
            { "warlock_the_archfey", "邪术师｜职业：攻0，防−1，距离∞；距离1以内钝击伤害，距离超过1穿刺伤害。\n\n妖精步伐｜主动技能：成为攻击目标时，若持有与攻击数字相同的手，可以令该手点数永久+1，取消攻击并使攻击者魅惑2回合。\n\n斗转星移｜主动技能：回合开始时，若自身体力未满，可以跳过本回合，选择一名体力与自己不同的其他角色，将其体力改为与自己相同。" },
            { "warlock_the_great_old_one", "邪术师｜职业：攻0，防−1，距离∞；距离1以内钝击伤害，距离超过1穿刺伤害。\n\n异界武备｜子职：距离1以内的普通攻击改为挥砍伤害。\n\n思维之盾｜被动技能：攻击命中时，使自己与目标之间的距离+2，持续至目标完成2个自身回合；仅影响双方，再次命中刷新时长、不叠加距离。该技能不属于负面状态，不受格挡或抗性的减时长影响。" },
            { "wizard_school_of_evocation", "法师｜职业：攻0，防−1，距离∞；距离1以内钝击伤害，距离超过1穿刺伤害。\n\n法术塑形｜主动技能：运算打出4、6或8时，可以放弃本次攻击，选择一种魔法伤害类型，将下次攻击改为该类型。消耗所选类型前，获得对应伤害类型的抗性；发起下次攻击时消耗附魔及该抗性，命中附加对应效果；闪避或取消也消耗附魔，新附魔覆盖旧附魔。" },
            { "sorcerer_wild_magic", "术士｜职业：攻0，防−1，距离∞；距离1以内钝击伤害，距离超过1穿刺伤害。\n\n狂野魔法浪涌｜被动技能：每段攻击随机判定，十种魔法伤害类型的出现概率各为8%，合计80%；其余20%保持普通伤害。命中后按伤害类型附加对应效果。" },
            { "bard_college_of_valor", "吟游诗人｜职业：攻0，防−1，距离1，钝击伤害。\n\n勇气训练｜子职：距离改为3，攻击改为穿刺伤害。\n\n战斗激励｜主动技能：自身行动结束后，若本回合受到过伤害或实际回复过体力，可以选择攻击范围内1～3名角色，统一增加或降低其攻击或防御。选择1、2、3名角色时，调整量分别为3、2、1；可以选择自己，持续至下次发动或自己死亡。" },
            { "rogue_swashbuckler", "游荡者｜职业：攻0，防−1，距离1，挥砍伤害。\n\n轻装决斗｜子职：防−1。\n\n梦幻舞步｜主动技能：受到可闪避的攻击时，可以将一只可用的1变为2，闪避该段攻击。\n\n潇洒无畏｜主动技能：发起攻击时，若另一只手为可用的2，可以将其变为3，令本次攻击基础伤害×1.5、距离改为∞、伤害改为穿刺，命中附加2回合流血。" },
            { "ranger_gloom_stalker", "游侠｜职业：攻+1，防−1，距离1，挥砍伤害。\n\n恐惧伏击｜主动技能：运算后，若双手同为1、2或3，可以将本次运算手暗置，进入伏击；伏击期间额外攻击+2、距离改为3、攻击改为穿刺，暗置手不能运算或作为加数。\n\n阴影闪避｜被动技能：伏击期间受到攻击时，解除伏击并抵挡该段伤害；次级咒术穿透伏击，也不会使其解除。" },
            { "rogue_thief", "游荡者｜职业：攻0，防−1，距离1，挥砍伤害。\n\n快手｜主动技能：可以放弃正常运算，交换自己与另一名角色各一只手的点数，不限距离，可以选择队友。若自己原点数不小于偷来的点数，按偷来的数字触发效果；否则只交换点数。不能连续两次行动发动偷窃。" },
            { "rogue_assassin", "游荡者｜职业：攻0，防−1，距离1，挥砍伤害。\n\n刺杀训练｜子职：攻+2，攻击改为穿刺伤害。\n\n暗杀｜被动技能：经运算达成双7时，进入潜行，无法成为攻击目标；手值不再为双7时，解除潜行。\n\n专业渗透｜主动技能：潜行期间，可以跳过一次自身行动，保留潜行；每次潜行限发动一次。\n\n死亡突袭｜被动技能：从潜行状态发起攻击时，本次攻击伤害+7，命中附加2回合流血。" },
            { "rogue_magician", "游荡者｜职业：攻0，防−1，距离1，挥砍伤害。\n\n魔术训练｜子职：距离改为2，攻击改为穿刺伤害。\n\n法师之手｜被动技能：自己的另一只手也可以作为加数；一只手不能与自身运算。\n\n诡术打击｜被动技能：运算打出2、4、6或8时，均发起对应点数的攻击。" },
            { "fighter_swordsman", "战士｜职业：攻+1，防0，距离1，挥砍伤害。\n\n剑术专精｜子职：攻+1，防−1。\n\n双刃连斩｜主动技能：运算后，若双手同为4、6或8，可以在本次主攻击前追加一次同值攻击。追加攻击无视双方攻防修正，命中附加2回合流血。" },
            { "monk_way_of_the_tai_chi", "武僧｜职业：攻0，防0，距离1，钝击伤害。气单武僧初始2、双武僧初始4、上限6；正常行动后双手点数相同获得1气，双将共用一份气，同次行动至多获得1气。\n\n阴阳流转｜被动技能：5改为太极形态，不形成普通护盾；太极化解后变为0，0被其他角色借作加数时先变为1。\n\n太极八卦｜主动技能：受到攻击时，可以将一只太极5变为0，使该段伤害减半，并将剩余一半反弹给攻击方；奇数伤害由自己承受较大一半。不能化解力场或穿透化解的攻击。\n\n借力打力｜主动技能：发动太极八卦时，可以消耗1气，选择自己不受该段伤害且仍反弹一半，或自己承受一半且反弹全部伤害；每只太极分别选择并消耗。" },
            { "monk_way_of_the_ninja", "武僧｜职业：攻0，防0，距离1，钝击伤害。气单武僧初始2、双武僧初始4、上限6；正常行动后双手点数相同获得1气，双将共用，同次至多获得1气。\n\n影分身｜主动技能：发起攻击时，可以消耗1气，使本次攻击基础伤害减半，攻击两段；每段分别计算攻防与防护。可以不发动而照常攻击一段。" },
            { "barbarian_path_of_the_warden", "野蛮人｜职业：攻0，防0，距离1，钝击伤害。\n\n守望体魄｜子职：防+1。\n\n守望束缚｜主动技能：形成盾牌时，可以锁定对手一只手，直到自己的对应盾牌破碎。场上只剩两名角色时，最多维持一只锁手；多人时最多维持两只。" },
            { "barbarian_path_of_the_berserker", "野蛮人｜职业：攻0，防0，距离1，钝击伤害。\n\n狂战体魄｜子职：攻−1，防−2，体力上限+5，攻击改为挥砍伤害。\n\n狂怒｜被动技能：运算打出9时，改为发起一次基础伤害为9的攻击。\n\n狂乱｜被动技能：每损失5点体力，额外获得攻防各+1；该加成随已损体力变化。\n\n嗜血｜被动技能：攻击实际造成伤害后，回复该次伤害的一半体力，向下取整。" },
            { "barbarian_path_of_the_giant", "野蛮人｜职业：攻0，防0，距离1，钝击伤害。\n\n巨人体魄｜子职：攻+2，防+2，体力上限+5。\n\n巨人之力｜被动技能：运算打出5时，改为两段攻击，每段基础伤害等于另一只手的点数。\n\n巨人恢复｜被动技能：运算打出9时，改为两段回复，每段回复量等于另一只手的点数。\n\n迟缓本能｜被动技能：运算打出4、6或8时，不触发数字效果。" },
            { "barbarian_path_of_the_beast", "野蛮人｜职业：攻0，防0，距离1，钝击伤害。\n\n野兽体魄｜子职：攻−2，防−2，体力上限+5，攻击改为挥砍伤害。\n\n野兽形态｜被动技能：运算后，若双手点数之和为7，回复体力上限的一半，向下取整，并永久获得攻防各+1。" },
            { "rogue_gambler", "游荡者｜职业：攻0，防−1，距1，挥砍。\n\n赌桌历练｜子职：防+1。\n\n命运赌博｜主动技能：用1d9代替运算，按点数结算效果。\n\n赌徒之运｜被动技能：上一次正常运算后，下次必须赌博。\n\n恶之强运｜主动技能：得知首掷结果后，可失去1d5生命，重掷一次并采用新结果。" },
            { "fighter_tactician", "战士｜职业：攻+1，防0，距离1，挥砍伤害。\n\n战术训练｜子职：攻−1。\n\n战术眼光｜主动技能：运算前选择加法或减法。减法用自己的数字减去对方数字，按10取模，0记作1。例如−1记作9，−2记作8。" },
            { "wizard_school_of_divination", "法师｜职业：攻0，防−1，距离∞；距离1以内钝击伤害，距离超过1穿刺伤害。\n\n预兆｜被动技能：打出7时，记录另一只手的点数；0～9每个数字最多保留一份记录。每保有三个不同预兆，攻防各+1。\n\n预知未来｜主动技能：若手上有7，有角色运算完成后，可以消耗一个预兆，将其运算结果替换为该数字，再按新数字结算效果；可以选择自己，也可以不发动。" },
            { "wizard_school_of_necromancy", "法师｜职业：攻0，防−1，距离∞；距离1以内钝击伤害，距离超过1穿刺伤害。\n\n不死适应｜主动技能：受到攻击时，可以将一只可用的2变为1，抵挡该段攻击；不能抵挡力场攻击。\n\n惧怖收割｜主动技能：回合开始时，若有可用的1，可以选择一名其他角色，免费发起一次基础伤害为1的暗蚀攻击，不受双方攻防修正，不消耗正常行动；也可以放弃攻击。\n\n不死奴仆｜主动技能：有角色死亡时，可以与死者交换0～2对手值；每只手最多交换一次，只交换点数。" },
            { "wizard_school_of_abjuration", "法师｜职业：攻0，防−1，距离∞；距离1以内钝击伤害，距离超过1穿刺伤害。\n\n法术抗性｜被动技能：运算打出2时，选择一名角色，赋予物理抗性整组，或雷鸣、强酸、火焰、寒冷、闪电中的一种抗性；可以选择自己。该抗性持续至施法者死亡或再次发动本技能；再次发动先撤销上次赋予，不影响其他来源抗性。\n\n奥术守御｜主动技能：运算打出攻击数字时，可以放弃本次攻击，将该数字存入奥术守御，可以累积。此后扣除体力前优先用守御吸收伤害，每次吸收后清空全部守御，包括未用完的部分。" },
            { "cleric_light_domain", "牧师｜职业：攻0，防−1，距离∞；距离1以内钝击伤害，距离超过1穿刺伤害。回复数字可选择给其他存活角色回复。\n\n净化圣焰｜被动技能：普通攻击改为固定5点火焰伤害，穿透火焰抗性和免疫；命中附圣火、灼伤各2回合。\n\n圣焰赐福｜被动技能：回复附加2回合圣火。" },
            { "cleric_war_domain", "牧师｜职业：攻0，防−1，距离∞；距离1以内钝击伤害，距离超过1穿刺伤害。回复数字可选择给其他存活角色回复。\n\n战争祭司｜主动技能：回合开始时，每有一只攻击数字的手，可选择一名角色附加2回合战争祝福；同次不重复选择，可少选或不选。\n\n战争赐福｜被动技能：回复附加2回合战争祝福。" },
            { "fighter_battle_master", "战士｜职业：攻+1，防0，距离1，挥砍伤害。\n\n战技训练｜子职：攻−1，距离改为2。\n\n兵器运用｜被动技能：以4、6、8发起攻击时，伤害类型分别改为挥砍、钝击、穿刺。\n\n卓越战技｜主动技能：发起攻击时，可以按另一只手的点数选择招式：4或8可选流血、跛脚，6可选震慑、倒伏。本次攻击实际造成伤害后，对目标附加所选负面效果2回合。" },
            { "sorcerer_draconic_bloodline", "术士｜职业：攻0，防−1，距∞。近钝击，远穿刺。\n\n龙族先祖｜被动技能：首次自身回合选择寒冷、火焰、闪电、毒素或强酸。获得永久抗性。攻击有80%改为所选类型，其余按距离钝击或穿刺。该类型伤害穿透对应抗性与免疫。\n\n龙族体魄｜被动技能：所选元素命中时附对应负面效果，已有时尝试延长1回合。格挡和对应抗性各扣1回合，免疫阻止状态和反应。" },
            { "ranger_hunter", "游侠｜职业：攻+1，防−1，距1，挥砍。\n\n狩猎专精｜子职：距3，攻击改为穿刺。\n\n猎人印记｜主动技能：无效果运算后，可标记距离3内一名其他角色。\n\n灭族者｜主动技能：攻击后可追加攻击范围内的标记目标。\n\n巨像屠夫｜被动技能：攻击消耗目标标记，无视正防御，伤害增加目标当前体力与已损体力的较大值÷5（向下取整）。被格挡时仍追加等于自身正攻击加成的真实伤害。" },
            { "monk_way_of_the_open_hand", "武僧｜职业：攻0，防0，距离1，钝击伤害。气单武僧初始2、双武僧初始4、上限6；正常行动后双手点数相同获得1气，双将共用，同次至多获得1气。\n\n散打技巧｜主动技能：发起攻击时，可以消耗1气，使本次攻击命中后附加2回合倒伏或震慑。\n\n渗透劲｜主动技能：发起攻击时，可以消耗3气，命中后向目标打入暗劲。仅施加者后续首次命中该目标时引爆，造成该次攻击经攻防计算、盾与抗性减免前应有伤害的一半真实伤害，向下取整。盾挡算命中；闪避／取消不附加也不引爆。同名暗劲不叠加。\n\n混元体｜主动技能：自身回合开始时，若体力值等于气，可以移除所有气，回复移除气值两倍的体力；保留本回合正常行动。" },
            { "monk_way_of_the_four_elements", "武僧｜职业：攻防0，距1，钝击。初始2气，双武僧4气，上限6。同次正常行动后双手同值回1气。\n\n四象门徒｜主动技能：耗2气，将本次攻击改为火焰、寒冷、闪电、雷鸣或强酸。\n\n四象法门｜主动技能：受到上述元素攻击时，可耗1气获得对应抗性。" },
            { "druid_circle_of_spores", "德鲁伊｜职业：攻0，防0，距离1，钝击伤害。初始2点荒野充能；双德鲁伊初始充能相加。\n\n荒野形态｜主动技能：回合开始时，若双手点数之和为10，可以消耗1点荒野充能并跳过本回合，选择熊、狼、鹰或蛇。使用独立形态体力，原角色与双将另一子职的技能暂停；形态体力归零时恢复原体力并承受溢出伤害，每个自己回合结束可选择解除。\n\n孢子环绕｜被动技能：自己回合开始时，与自己距离1且体力低于自己的其他角色附加2回合腐朽。\n\n一体共生｜主动技能：回合开始时，若双手点数相同且没有孢子生命，可以消耗1点荒野充能获得10点孢子生命；存在期间攻击改为毒素。孢子生命先于虚假生命吸收伤害，溢出部分继续结算；无回合期限，耗尽后可重新发动。\n\n真菌感染｜被动技能：距离1的其他非召唤角色真正死亡时，恢复1点荒野充能，最多恢复至本局初始总量；形态解除不算死亡。" },
            { "druid_circle_of_the_moon", "德鲁伊｜职业：攻0，防0，距离1，钝击伤害。初始2点荒野充能；双德鲁伊初始充能相加。\n\n荒野形态｜主动技能：回合开始时，若双手点数之和为10，可以消耗1点荒野充能并跳过本回合，选择熊、狼、鹰或蛇。使用独立形态体力，原角色与双将另一子职的技能暂停；形态体力归零时恢复原体力并承受溢出伤害，每个自己回合结束可选择解除。\n\n月之魔力｜子职：初始荒野充能+1；可消耗2点充能变为枭熊或黑豹。\n\n结社形态｜形态说明：熊12体力，攻−1／防+1，距离1挥砍，4改为合盾；狼10体力，攻0／防−1，距离1挥砍，回复每段实际生命伤害的一半，向下取整；鹰8体力，攻+1／防−1，距离3穿刺，6不能攻击；蛇8体力，攻0／防0，距离1毒素。\n\n枭熊｜形态说明：16体力，攻0／防+2，距离2挥砍；攻击基础伤害增加双方距离。\n\n黑豹｜形态说明：10体力，攻+2／防0，距离1挥砍；攻击命中附加2回合流血。" },
            { "druid_circle_of_the_stars", "德鲁伊｜职业：攻0，防0，距离1，钝击伤害。初始2点荒野充能；双德鲁伊初始充能相加。\n\n荒野形态｜主动技能：回合开始时，若双手点数之和为10，可以消耗1点荒野充能并跳过本回合，选择熊、狼、鹰或蛇。使用独立形态体力，原角色与双将另一子职的技能暂停；形态体力归零时恢复原体力并承受溢出伤害，每个自己回合结束可选择解除。\n\n观星修行｜子职：进入荒野时额外选择一种星耀形态；两者攻防相加、距离取高，一并解除。\n\n射手座｜形态说明：攻+2／防−1，距离3，攻击改为光耀。\n\n圣杯座｜形态说明：攻0／防0，距离1，荒野形态体力上限+4；运算打出9回复后，可以额外选择一名存活角色（可选自己）回复9体力。\n\n巨龙座｜形态说明：攻+1／防+1，距离3；回合开始可以纯运算一次，未进行则回合结束必须纯运算一次，无合法运算时略过。\n\n结社形态｜形态说明：熊12体力，攻−1／防+1，距离1挥砍，4改为合盾；狼10体力，攻0／防−1，距离1挥砍，回复每段实际生命伤害的一半，向下取整；鹰8体力，攻+1／防−1，距离3穿刺，6不能攻击；蛇8体力，攻0／防0，距离1毒素。" },
            { "druid_circle_of_the_land", "德鲁伊｜职业：攻0，防0，距离1，钝击伤害。初始2点荒野充能；双德鲁伊初始充能相加。\n\n荒野形态｜主动技能：回合开始时，若双手点数之和为10，可以消耗1点荒野充能并跳过本回合，选择熊、狼、鹰或蛇。使用独立形态体力，原角色与双将另一子职的技能暂停；形态体力归零时恢复原体力并承受溢出伤害，每个自己回合结束可选择解除。\n\n大地束缚｜主动技能：运算打出3时，可以选择另一名角色附加2回合束缚。\n\n大地行者｜主动技能：回合结束时，若双手都没有3，可以选择自己一只手，使其不能成为被加数，直到自己下回合开始。\n\n结社形态｜形态说明：熊12体力，攻−1／防+1，距离1挥砍，4改为合盾；狼10体力，攻0／防−1，距离1挥砍，回复每段实际生命伤害的一半，向下取整；鹰8体力，攻+1／防−1，距离3穿刺，6不能攻击；蛇8体力，攻0／防0，距离1毒素。" },
            { "paladin_oath_of_the_ancients", "圣武士｜职业：攻0，防0，距离1，钝击伤害。\n\n古贤护身｜子职：攻−1，防+1。\n\n自然之怒｜主动技能：自己的盾牌破碎时，可以选择攻击范围内一名其他角色，对其附加2回合束缚。\n\n不灭哨卫｜被动技能：受到伤害后，若仍存活且体力不低于10，选择攻击范围内一名其他角色，使其回复2点体力；若体力低于10，改为自己回复2点体力。" },
            { "warlock_the_fiend", "邪术师｜职业：攻0，防−1，距离∞；距离1以内钝击伤害，距离超过1穿刺伤害。\n\n黑暗赐福｜被动技能：回复体力溢出时，将溢出量存为虚假生命，最多10点；受到伤害时，优先消耗虚假生命。\n\n直坠噩梦｜主动技能：发起攻击时，可以耗尽当前虚假生命，令本次攻击命中后附加2回合失能或恐慌。\n\n黑暗强运｜被动技能：攻击实际造成伤害后，若目标剩余体力不高于其体力上限的一半，回复3点体力；击杀目标也能触发。" },
            { "bard_college_of_lore", "吟游诗人｜职业：攻0，防−1，距离1，钝击伤害。\n\n逸闻记录｜被动技能：记录自己打出的1～9，每个数字只保留一份记录。\n\n无与伦比技艺｜主动技能：回合结束时，若已集齐1～9的记录，可以清空全部记录，永久获得攻、防、距离各+1。\n\n切割语｜主动技能：受到攻击时，若已记录该攻击数字，可以清除这份记录，使本次攻击伤害减半。" },
            { "sorcerer_shadow_magic", "术士｜职业：攻0，防−1，距离∞；距离1以内钝击伤害，距离超过1穿刺伤害。\n\n坟冢之力｜被动技能：体力首次归0时恢复至1，每局一次。\n\n黑暗术｜主动技能：回合结束时，若双手点数之和为10，可令距离1以内的所有角色失明2回合。\n\n幽暗之瞳｜被动技能：免疫失明；攻击失明角色时，伤害+2并改为暗蚀伤害。" },
            { "sorcerer_storm_sorcery", "术士｜职业：攻0，防−1，距∞。近钝击，远穿刺。\n\n风暴之护｜被动技能：首次自身回合选择永久闪电或雷鸣抗性。\n\n暴风狂怒｜被动技能：攻击各有40%改为闪电或雷鸣。两种伤害均穿透对应抗性与免疫。抗性仍扣附加状态1回合，免疫仍阻止状态和反应。\n\n风暴导向｜主动技能：正常行动后可额外纯运算一次。" },
            { "wizard_school_of_illusion", "法师｜职业：攻0，防−1，距离∞；距离1以内钝击伤害，距离超过1穿刺伤害。\n\n幻术默发｜主动技能：若手上有2，当其他角色选择你的任意一只手作为加数时，可以查看其运算手和原加数，再选择是否改用自己的另一只合法手作为加数。\n\n幻影实体｜主动技能：受到攻击时，若双手点数之差为2，可以将点数较小的手变为2，使本次攻击伤害减半。" },
            { "wizard_school_of_transmutation", "法师｜职业：攻0，防−1，距离∞；距离1以内钝击伤害，距离超过1穿刺伤害。\n\n变形术｜主动技能：回合结束时，可以选择一名双手点数与自己无序匹配的角色，对其施加2回合变羊，可以选择自己。\n\n变形生物｜形态说明：变为羊时，使用独立的8点体力，攻防改为−2/−2、距离改为1，暂停原角色技能，原有状态继续计时。解除后恢复原体力与技能；羊形态体力归0时提前解除，溢出伤害由原形态承受。\n\n变化莫测｜主动技能：有角色变羊或解除变羊时，可以立即额外运算一次，照常结算数字效果。自己变羊时暂停此技能，恢复原形后可以发动。" },
            { "wizard_school_of_enchantment", "法师｜职业：攻0，防−1，距离∞；距离1以内钝击伤害，距离超过1穿刺伤害。\n\n催眠凝视｜主动技能：实际造成伤害后，可以对受伤目标附加2回合魅惑；实际受到伤害后，可以对伤害来源附加2回合失能。效果在本次伤害结算后施加，目标之后实际损失体力时解除。" },
            { "fighter_eldritch_knight", "战士｜职业：攻+1，防0，距离1，挥砍伤害。\n\n奥法武备｜子职：攻−1，距离改为2。\n\n奥法武器｜主动技能：自己的盾牌破碎时，可以选择一种元素，将下次攻击改为该类型。新附魔覆盖旧附魔，发起攻击时消耗，命中后按类型附加对应效果；使用完整盾牌运算后发起攻击，附魔立即用于本次攻击。\n\n法术回响｜主动技能：受到非物理伤害并实际损失体力后，可以记录该伤害类型，将下次攻击改为该类型。" },
            { "wizard_bladesinging", "法师｜职业：攻0，防−1，距离∞；距离1以内钝击伤害，距离超过1穿刺伤害。\n\n剑咏训练｜子职：距离改为2，攻击改为挥砍伤害。\n\n剑歌｜主动技能：回合结束时，若双手点数之和等于自身体力，可以选择一种元素，进入剑歌；期间攻防各+1，攻击改为所选元素伤害。\n\n守御之歌｜被动技能：进入剑歌的当回合保留剑歌；之后自身每回合必须发起未被取消的攻击、形成盾牌或实际回复体力，否则回合结束时失去剑歌。" },
            { "paladin_oath_of_conquest", "圣武士｜职业：攻0，防0，距离1，钝击伤害。\n\n征服威压｜被动技能：发起攻击时若手上有5，本次攻击结束后获得攻击+1；受到攻击时若手上有5，本次攻击结束后获得防御+1。一次多段攻击只获得一次对应加成。\n\n恐惧光环｜被动技能：发起攻击时，若自身攻击加成高于目标，对目标附加2回合恐慌；受到攻击时，若自身防御加成高于攻击者，对攻击者附加2回合恐慌。比较攻击开始时的数值，效果在本次攻击结束后附加。\n\n威势衰减｜被动技能：回合结束时，若本回合未发起攻击，本技能积累的攻击加成−1；若手上没有5，本技能积累的防御加成−1，均最低减至0。攻击被取消时，不成长、不附加恐慌，并视为未发起攻击。" },
            { "cleric_trickery_domain", "牧师｜职业：攻0，防−1，距离∞；距离1以内钝击伤害，距离超过1穿刺伤害。回复数字可选择给其他存活角色回复。\n\n诡诈换位｜主动技能：其他角色借你的手运算时，若你的原加数、对方原运算手或本次运算结果中有2，可以交换你的原加数与对方的运算结果；对方按交换后的数字触发本次效果。\n\n诡术魅惑｜主动技能：成功发动诡诈换位后，可以对该运算者附加2回合魅惑。\n\n诡术赐福｜主动技能：回复结束后，可选择受疗者一只手变为2。" },
            { "cleric_tempest_domain", "牧师｜职业：攻0，防−1，距离∞；距离1以内钝击伤害，距离超过1穿刺伤害。回复数字可选择给其他存活角色回复。\n\n风暴之心｜主动技能：回合开始时，可以进行一次纯运算。\n\n风暴之怒｜主动技能：受到攻击时，若手上有4，可以在来袭伤害结算前选择一只4，对攻击者发起一次基础伤害为4的闪电或雷鸣反击，随后必须用同一只手进行一次纯运算。整次来袭限发动一次；反击不触发风暴之怒，反击击杀来袭者时终止其原攻击。\n\n风暴赐福｜主动技能：回复后，可令受疗者立即进行一次纯运算。" },
            { "paladin_oath_of_vengeance", "圣武士｜职业：攻0，防0，距离1，钝击伤害。\n\n仇敌誓言｜被动技能：本局首次自身回合开始时，选择一名其他角色作为仇敌；同时只能标记一名角色。\n\n誓言转移｜主动技能：其他角色向你发起攻击时，可以将仇敌标记转移给攻击者；仇敌死亡时，可以重新选择一名其他角色作为仇敌。\n\n坚韧复仇者｜被动技能：攻击仇敌时，每段攻击伤害+1；攻击其他角色时，每段攻击伤害−1。\n\n复仇之魂｜主动技能：仇敌每破坏自己一面盾牌，可以立即进行一次纯运算，也可以放弃；普通攻击破盾和主动破阵强袭均可触发。" },
            { "monk_way_of_the_drunken_master", "武僧｜职业：攻0，防0，距离1，钝击伤害。气单武僧初始2、双武僧初始4、上限6；正常行动后双手点数相同获得1气，双将共用，同次至多获得1气。\n\n醉拳技巧｜主动技能：未入醉时打出9，先正常回复，再可以进入醉拳状态。\n\n酣醉若狂｜被动技能：自身回合开始时，若处于醉拳状态，消耗1气；气不足则解除醉拳。\n\n醉拳｜角色状态：所有数字改为攻击，5不合盾、9不回复；每段基础伤害为1d10。受到非零攻击伤害时，每段改为1d5，再计算抗性、盾牌和屏障。持续状态伤害与注明不可增减的固定伤害保持原规则；圣火清除并阻止醉拳。" },
            { "warlock_the_hexblade", "邪术师｜职业：攻0，防−1，距∞。近钝击，远穿刺。\n\n咒剑武备｜子职：攻+1，距2，攻击改为挥砍。\n\n咒剑诅咒｜主动技能：无效果运算后，可诅咒一名其他角色，时长等于运算结果。只维持一个目标。\n\n咒剑战士｜被动技能：对诅咒目标每段攻击+2伤害。\n\n咒缚幽灵｜被动技能：亲自击杀诅咒目标后，在其座位召唤继承手值的幽灵。下轮开始行动，占位计距。召唤者死亡或召唤新幽灵时，旧幽灵消失。" },
        };
        public static bool TryGet(string id, out string text) => ById.TryGetValue(id, out text);
    }
